	VMOVI   $0xC2, V25.B16
	VMOVI   $0xFE, V26.B16
	VMOVI   $0x40, V27.B16
	VMOVI   $0xC3, V28.B16
	VMOVI   $0x3F, V29.B16
	VMOVI   $0x0F, V30.B16
	VMOVI   $0xC0, V31.B16
	MOVD    $0, R3
	MOVD    R4, R0
	VEOR    V14.B16, V14.B16, V14.B16
	VEOR    V12.B16, V12.B16, V12.B16

slatin1:
	SUB     R3, R2, R7
	CMP     $0, R7
	BLE     slatin1Done
	ADD     R3, R1, R6
	CMP     $16, R7
	BLT     sltail
	VLD1    (R6), [V0.B16]
	LDP     (R6), (R8, R9)

slbody:
	ORR     R8, R9, R10
	TST     R22, R10
	BNE     slchars
	// ASCII: no char of the block before may be cut.
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VST1    [V0.B16], (R0)
	ADD     $16, R0
	VORR    V0.B16, V0.B16, V14.B16
	ADD     $16, R3
	B       slatin1

slchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start. A byte b of 80 or above is C4
	// or above when (b & 7F) + 3C carries into its high bit.
	AND     $0x7f7f7f7f7f7f7f7f, R8, R10
	ADD     R19, R10, R10
	AND     R8, R10, R10
	AND     $0x7f7f7f7f7f7f7f7f, R9, R11
	ADD     R19, R11, R11
	AND     R9, R11, R11
	ORR     R10, R11, R10
	TST     R22, R10
	BNE     stoUTF16
	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly the
	// bytes after the leads, and there are no C0 or C1.
	VEXT    $15, V0.B16, V14.B16, V2.B16 // the byte before each
	VAND    V26.B16, V0.B16, V7.B16
	VCMEQ   V25.B16, V7.B16, V4.B16      // the leads
	VCMEQ   V31.B16, V7.B16, V7.B16      // C0 and C1
	VORR    V7.B16, V12.B16, V12.B16
	VAND    V26.B16, V2.B16, V5.B16
	VCMEQ   V25.B16, V5.B16, V5.B16      // after a lead
	WORD $0x4e2037e6 //    CMGT V0.B16, V31.B16, V6.B16 // continuations
	VEOR    V6.B16, V5.B16, V5.B16
	VORR    V5.B16, V12.B16, V12.B16
	VCMEQ   V28.B16, V2.B16, V5.B16
	VAND    V27.B16, V5.B16, V5.B16
	VADD    V5.B16, V0.B16, V6.B16       // the bytes: 40 more after C3
	VORR    V0.B16, V0.B16, V14.B16
	WORD $0x0f0c848b //    SHRN $4, V4.H8, V11.B8
	VMOV    V11.D[0], R8
	MVN     R8, R8
	AND     $0x1111111111111111, R8
	ORR     R8>>3, R8, R8
	AND     $0x0303030303030303, R8
	ORR     R8>>6, R8, R8
	AND     $0x000F000F000F000F, R8
	ORR     R8>>12, R8, R8
	AND     $0xff, R8, R9
	UBFX    $32, R8, $8, R10
	// kept: all but the leads
	FMOVD   (R23)(R9<<3), F8
	MOVD    (R24)(R10<<3), R11
	VMOV    R11, V8.D[1]
	VTBL    V8.B16, [V6.B16], V6.B16
	MOVBU   (R20)(R9), R9
	MOVBU   (R20)(R10), R10
	VST1    [V6.B16], (R0)
	SUB     $8, R9, R9
	ADD     R9, R0
	VMOV    V6.D[1], R11
	MOVD    R11, (R0)
	SUB     $8, R10, R10
	ADD     R10, R0
	ADD     $16, R3
	B       slatin1

sltail:
	AND     $4095, R6, R8
	CMP     $4080, R8
	BHI     slcross
	VLD1    (R6), [V0.B16]
	ADD     $(N_MASK+16), R21, R8
	SUB     R7, R8, R8
	VLD1    (R8), [V1.B16]
	VAND    V1.B16, V0.B16, V0.B16
	VMOV    V0.D[0], R8
	VMOV    V0.D[1], R9
	B       slbody

slcross:
	VEOR    V0.B16, V0.B16, V0.B16
	VST1    [V0.B16], (R0)
	MOVD    $0, R8

slbyte:
	MOVBU   (R6)(R8), R9
	MOVB    R9, (R0)(R8)
	ADD     $1, R8
	CMP     R7, R8
	BLT     slbyte
	VLD1    (R0), [V0.B16]
	LDP     (R0), (R8, R9)
	B       slbody

slatin1Done:
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VMOV    V12.D[0], R8
	VMOV    V12.D[1], R9
	ORR     R8, R9, R10
	CBNZ    R10, sinvalid
	SUB     R4, R0, R7
	SUB     R2, R3, R8                   // the zeros past the text
	SUB     R8, R7, R7
	B       sdone

stoUTF16:
	// From the start again, as UTF-16: the block in V0 when it is the first.
	MOVD    R5, R0
	MOVD    $0, R13                      // the block before has a lead of 4 bytes (or more)
	VEOR    V14.B16, V14.B16, V14.B16
	VEOR    V12.B16, V12.B16, V12.B16
	CBZ     R3, swchars
	MOVD    $0, R3

swide:
	SUB     R3, R2, R7
	CMP     $0, R7
	BLE     swideDone
	ADD     R3, R1, R6
	CMP     $16, R7
	BLT     swtail
	VLD1    (R6), [V0.B16]
	LDP     (R6), (R8, R9)

swbody:
	ORR     R8, R9, R10
	TST     R22, R10
	BNE     swchars
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VUXTL   V0.B8, V4.H8
	VUXTL2  V0.B16, V5.H8
	VST1    [V4.B16, V5.B16], (R0)
	ADD     $32, R0
	MOVD    $0, R13
	VORR    V0.B16, V0.B16, V14.B16
	ADD     $16, R3
	B       swide

swchars:
	// Check the block (Keiser and Lemire): V2 the byte one before each, V3 two before, V1 three before.
	VEXT    $15, V0.B16, V14.B16, V2.B16
	VEXT    $14, V0.B16, V14.B16, V3.B16
	VEXT    $13, V0.B16, V14.B16, V1.B16
	VUSHR   $4, V2.B16, V4.B16
	VTBL    V4.B16, [V20.B16], V4.B16
	VAND    V30.B16, V2.B16, V5.B16
	VTBL    V5.B16, [V21.B16], V5.B16
	VUSHR   $4, V0.B16, V6.B16
	VTBL    V6.B16, [V22.B16], V6.B16
	VAND    V5.B16, V4.B16, V4.B16
	VAND    V6.B16, V4.B16, V4.B16
	WORD $0x6e322c65 //    UQSUB V18.B16, V3.B16, V5.B16
	WORD $0x6e312c26 //    UQSUB V17.B16, V1.B16, V6.B16
	VORR    V6.B16, V5.B16, V5.B16
	VAND    V13.B16, V5.B16, V5.B16
	VEOR    V5.B16, V4.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VORR    V0.B16, V0.B16, V14.B16
	// A lead of 4 bytes (F0 or above) here or in the block before: surrogates (R12).
	AND     $0x7f7f7f7f7f7f7f7f, R8, R10
	ADD     R17, R10, R10
	AND     R8, R10, R10
	AND     $0x7f7f7f7f7f7f7f7f, R9, R11
	ADD     R17, R11, R11
	AND     R9, R11, R11
	ORR     R10, R11, R10
	AND     R22, R10, R10
	ORR     R10, R13, R12
	MOVD    R10, R13
	WORD $0x4e2037e4 //    CMGT V0.B16, V31.B16, V4.B16 // b0 a continuation
	WORD $0x4e2237e5 //    CMGT V2.B16, V31.B16, V5.B16 // b1 a continuation
	VAND    V24.B16, V2.B16, V6.B16
	VCMEQ   V31.B16, V6.B16, V6.B16      // b1 the lead of 2 bytes
	WORD $0x4e20a807 //    CMLT V0.B16, V7.B16          // b0 not ASCII
	VORR    V6.B16, V5.B16, V5.B16
	VAND    V4.B16, V5.B16, V5.B16       // b0 ends a char of 2 or more bytes, or is a third byte
	WORD $0x4ee71ca5 //    ORN V7.B16, V5.B16, V5.B16   // kept: those and ASCII
	WORD $0x0f0c84ab //    SHRN $4, V5.H8, V11.B8
	VMOV    V11.D[0], R8
	AND     $0x1111111111111111, R8
	ORR     R8>>3, R8, R8
	AND     $0x0303030303030303, R8
	ORR     R8>>6, R8, R8
	AND     $0x000F000F000F000F, R8
	ORR     R8>>12, R8, R8
	AND     $0xff, R8, R9
	UBFX    $32, R8, $8, R10
	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VORR    V0.B16, V0.B16, V4.B16
	VSLI    $6, V2.B16, V4.B16
	VBIF    V7.B16, V0.B16, V4.B16
	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VUSHR   $2, V2.B16, V5.B16
	VAND    V30.B16, V5.B16, V5.B16
	VSHL    $4, V3.B16, V8.B16
	VORR    V5.B16, V8.B16, V8.B16
	VBIT    V6.B16, V5.B16, V8.B16
	VAND    V7.B16, V8.B16, V8.B16
	CBZ     R12, swpack
	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VAND    V15.B16, V3.B16, V9.B16
	VCMEQ   V23.B16, V9.B16, V9.B16
	VAND    V15.B16, V1.B16, V10.B16
	VCMEQ   V23.B16, V10.B16, V10.B16
	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VAND    V29.B16, V2.B16, V6.B16
	VSHL    $2, V6.B16, V6.B16
	VUSHR   $4, V0.B16, V7.B16
	VMOVI   $3, V11.B16
	VAND    V11.B16, V7.B16, V7.B16
	VORR    V7.B16, V6.B16, V6.B16
	VSUB    V27.B16, V6.B16, V7.B16
	VBIT    V9.B16, V7.B16, V4.B16
	VCMTST  V31.B16, V6.B16, V6.B16      // no borrow
	VMOVI   $7, V11.B16
	VAND    V11.B16, V3.B16, V7.B16
	VMOVI   $0xD7, V11.B16
	VADD    V11.B16, V7.B16, V7.B16
	VSUB    V6.B16, V7.B16, V7.B16
	VBIT    V9.B16, V7.B16, V8.B16
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VMOVI   $3, V11.B16
	VAND    V11.B16, V5.B16, V7.B16
	VMOVI   $0xDC, V11.B16
	VORR    V11.B16, V7.B16, V7.B16
	VBIT    V10.B16, V7.B16, V8.B16

swpack:
	VZIP1   V8.B16, V4.B16, V9.B16       // the units of positions 0 to 7
	VZIP2   V8.B16, V4.B16, V10.B16      // 8 to 15
	ADD     R9<<4, R25, R11
	VLD1    (R11), [V6.B16]
	ADD     R10<<4, R25, R11
	VLD1    (R11), [V7.B16]
	MOVBU   (R20)(R9), R9
	MOVBU   (R20)(R10), R10
	VTBL    V6.B16, [V9.B16], V9.B16
	VTBL    V7.B16, [V10.B16], V10.B16
	VST1    [V9.B16], (R0)
	ADD     R9<<1, R0, R0
	SUB     $16, R0, R0
	VST1    [V10.B16], (R0)
	ADD     R10<<1, R0, R0
	SUB     $16, R0, R0
	ADD     $16, R3
	B       swide

swtail:
	AND     $4095, R6, R8
	CMP     $4080, R8
	BHI     swcross
	VLD1    (R6), [V0.B16]
	ADD     $(N_MASK+16), R21, R8
	SUB     R7, R8, R8
	VLD1    (R8), [V1.B16]
	VAND    V1.B16, V0.B16, V0.B16
	VMOV    V0.D[0], R8
	VMOV    V0.D[1], R9
	B       swbody

swcross:
	VEOR    V0.B16, V0.B16, V0.B16
	VST1    [V0.B16], (R0)
	MOVD    $0, R8

swbyte:
	MOVBU   (R6)(R8), R9
	MOVB    R9, (R0)(R8)
	ADD     $1, R8
	CMP     R7, R8
	BLT     swbyte
	VLD1    (R0), [V0.B16]
	LDP     (R0), (R8, R9)
	B       swbody

swideDone:
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VMOV    V12.D[0], R8
	VMOV    V12.D[1], R9
	ORR     R8, R9, R10
	CBNZ    R10, sinvalid
	SUB     R5, R0, R7
	LSR     $1, R7, R7
	SUB     R2, R3, R8                   // the zeros past the text
	SUB     R8, R7, R7
	MVN     R7, R7
	B       sdone

sinvalid:
	MOVD    $0x7fffffffffffffff, R7
	B       sdone

sdone:
	MOVD    R7, ret+32(FP)
	RET

// func wireStringsNEON(dst unsafe.Pointer, room int, strs unsafe.Pointer, count int, ptrs bool) (done, written int)
//
// It writes strings from strs (count of them: strings, or pointers to them when ptrs, nil the null string) at dst
// (room bytes), each with its one-byte header, while each has room for 1+2*len+wireSlack bytes and is WTF-8 of fewer
// than wireMaxText (64) bytes, so of at most 63 chars; it returns how many it wrote and the bytes they took.
TEXT ·wireStringsNEON(SB), NOSPLIT, $0-56
	MOVD    dst+0(FP), R15           // where the next string goes
	MOVD    room+8(FP), R16
	ADD     R15, R16, R16            // the end of the room
	MOVD    $0, R14                  // the strings done
	MOVD    $·pairLen(SB), R20
	MOVD    $wireN<>(SB), R21
	MOVD    $0x8080808080808080, R22
	MOVD    $·narrowLo(SB), R23
	MOVD    $·narrowHi(SB), R24
	MOVD    $·wideShuf(SB), R25
	MOVD    $0x3C3C3C3C3C3C3C3C, R19
	MOVD    $0x1010101010101010, R17
	ADD     $N_T1, R21, R8
	VLD1    (R8), [V20.B16, V21.B16, V22.B16]
	ADD     $N_TAIL, R21, R8
	VLD1    (R8), [V19.B16]
	VMOVI   $0x80, V13.B16
	VMOVI   $0xF8, V15.B16
	VMOVI   $0x70, V17.B16
	VMOVI   $0x60, V18.B16
	VMOVI   $0xF0, V23.B16
	VMOVI   $0xE0, V24.B16
	VMOVI   $0xC2, V25.B16
	VMOVI   $0xFE, V26.B16
	VMOVI   $0x40, V27.B16
	VMOVI   $0xC3, V28.B16
	VMOVI   $0x3F, V29.B16
	VMOVI   $0x0F, V30.B16
	VMOVI   $0xC0, V31.B16

	MOVD    count+24(FP), R26        // the strings to write
	// Each string costs a few instructions at least (short ASCII, the common case, about 30): the loop takes as few
	// as it can, with strings falling through to their header and pointers to strings taken out of line (mptr).

mnext:
	CMP     R26, R14
	BGE     mfinish
	MOVD    strs+16(FP), R9
	MOVBU   ptrs+32(FP), R10
	CBNZ    R10, mptr
	ADD     R14<<4, R9, R9

mheader:
	MOVD    (R9), R1
	MOVD    8(R9), R2
	CBNZ    R2, mtext
	ADD     $1, R15, R10
	CMP     R16, R10
	BHI     mfinish
	MOVD    $1, R11
	MOVB    R11, (R15)
	MOVD    R10, R15
	ADD     $1, R14
	B       mnext

mtext:
	CMP     $const_wireMaxText, R2
	BHS     mfinish
	ADD     R2<<1, R15, R10
	ADD     $(1+const_wireSlack), R10
	CMP     R16, R10
	BHI     mfinish
	// ASCII text of fewer than 16 bytes: the 16 bytes from the one before it, masked (where they lie in one page),
	// the header, 2n+1, in the first, stored where the string goes: the header and the text in one store (see the
	// amd64 list kernels).
	CMP     $16, R2
	BHS     mlong
	SUB     $1, R1, R6
	AND     $4095, R6, R8
	CMP     $4080, R8
	BHI     mlong
	VLD1    (R6), [V0.B16]
	ADD     $(N_MASK+15), R21, R8
	SUB     R2, R8, R8
	VLD1    (R8), [V1.B16]
	VAND    V1.B16, V0.B16, V0.B16
	// The header 2n+1 as (n+1)+n, n+1 also the bytes the string takes; ASCII when the largest byte is below 0x80.
	ADD     $1, R2, R8
	ADD     R2, R8, R11
	VMOV    R11, V0.B[0]
	WORD $0x6e30a802 //    UMAXV V0.B16, V2
	VMOV    V2.B[0], R10
	TBNZ    $7, R10, mlong
	VST1    [V0.B16], (R15)
	ADD     R8, R15, R15
	ADD     $1, R14
	B       mnext

mptr:
	MOVD    (R9)(R14<<3), R9
	CBNZ    R9, mheader
	// nil: the null string.
	ADD     $1, R15, R10
	CMP     R16, R10
	BHI     mfinish
	MOVB    ZR, (R15)
	MOVD    R10, R15
	ADD     $1, R14
	B       mnext

mlong:
	ADD     $1, R15, R4
	MOVD    R4, R5
	MOVD    $0, R3
	MOVD    R4, R0
	VEOR    V14.B16, V14.B16, V14.B16
	VEOR    V12.B16, V12.B16, V12.B16

mlatin1:
	SUB     R3, R2, R7
	CMP     $0, R7
	BLE     mlatin1Done
	ADD     R3, R1, R6
	CMP     $16, R7
	BLT     mltail
	VLD1    (R6), [V0.B16]
	LDP     (R6), (R8, R9)

mlbody:
	ORR     R8, R9, R10
	TST     R22, R10
	BNE     mlchars
	// ASCII: no char of the block before may be cut.
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VST1    [V0.B16], (R0)
	ADD     $16, R0
	VORR    V0.B16, V0.B16, V14.B16
	ADD     $16, R3
	B       mlatin1

mlchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start. A byte b of 80 or above is C4
	// or above when (b & 7F) + 3C carries into its high bit.
	AND     $0x7f7f7f7f7f7f7f7f, R8, R10
	ADD     R19, R10, R10
	AND     R8, R10, R10
	AND     $0x7f7f7f7f7f7f7f7f, R9, R11
	ADD     R19, R11, R11
	AND     R9, R11, R11
	ORR     R10, R11, R10
	TST     R22, R10
	BNE     mtoUTF16
	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly the
	// bytes after the leads, and there are no C0 or C1.
	VEXT    $15, V0.B16, V14.B16, V2.B16 // the byte before each
	VAND    V26.B16, V0.B16, V7.B16
	VCMEQ   V25.B16, V7.B16, V4.B16      // the leads
	VCMEQ   V31.B16, V7.B16, V7.B16      // C0 and C1
	VORR    V7.B16, V12.B16, V12.B16
	VAND    V26.B16, V2.B16, V5.B16
	VCMEQ   V25.B16, V5.B16, V5.B16      // after a lead
	WORD $0x4e2037e6 //    CMGT V0.B16, V31.B16, V6.B16 // continuations
	VEOR    V6.B16, V5.B16, V5.B16
	VORR    V5.B16, V12.B16, V12.B16
	VCMEQ   V28.B16, V2.B16, V5.B16
	VAND    V27.B16, V5.B16, V5.B16
	VADD    V5.B16, V0.B16, V6.B16       // the bytes: 40 more after C3
	VORR    V0.B16, V0.B16, V14.B16
	WORD $0x0f0c848b //    SHRN $4, V4.H8, V11.B8
	VMOV    V11.D[0], R8
	MVN     R8, R8
	AND     $0x1111111111111111, R8
	ORR     R8>>3, R8, R8
	AND     $0x0303030303030303, R8
	ORR     R8>>6, R8, R8
	AND     $0x000F000F000F000F, R8
	ORR     R8>>12, R8, R8
	AND     $0xff, R8, R9
	UBFX    $32, R8, $8, R10
	// kept: all but the leads
	FMOVD   (R23)(R9<<3), F8
	MOVD    (R24)(R10<<3), R11
	VMOV    R11, V8.D[1]
	VTBL    V8.B16, [V6.B16], V6.B16
	MOVBU   (R20)(R9), R9
	MOVBU   (R20)(R10), R10
	VST1    [V6.B16], (R0)
	SUB     $8, R9, R9
	ADD     R9, R0
	VMOV    V6.D[1], R11
	MOVD    R11, (R0)
	SUB     $8, R10, R10
	ADD     R10, R0
	ADD     $16, R3
	B       mlatin1

mltail:
	AND     $4095, R6, R8
	CMP     $4080, R8
	BHI     mlcross
	VLD1    (R6), [V0.B16]
	ADD     $(N_MASK+16), R21, R8
	SUB     R7, R8, R8
	VLD1    (R8), [V1.B16]
	VAND    V1.B16, V0.B16, V0.B16
	VMOV    V0.D[0], R8
	VMOV    V0.D[1], R9
	B       mlbody

mlcross:
	VEOR    V0.B16, V0.B16, V0.B16
	VST1    [V0.B16], (R0)
	MOVD    $0, R8

mlbyte:
	MOVBU   (R6)(R8), R9
	MOVB    R9, (R0)(R8)
	ADD     $1, R8
	CMP     R7, R8
	BLT     mlbyte
	VLD1    (R0), [V0.B16]
	LDP     (R0), (R8, R9)
	B       mlbody

mlatin1Done:
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VMOV    V12.D[0], R8
	VMOV    V12.D[1], R9
	ORR     R8, R9, R10
	CBNZ    R10, minvalid
	SUB     R4, R0, R7
	SUB     R2, R3, R8                   // the zeros past the text
	SUB     R8, R7, R7
	B       mdone

mtoUTF16:
	// From the start again, as UTF-16: the block in V0 when it is the first.
	MOVD    R5, R0
	MOVD    $0, R13                      // the block before has a lead of 4 bytes (or more)
	VEOR    V14.B16, V14.B16, V14.B16
	VEOR    V12.B16, V12.B16, V12.B16
	CBZ     R3, mwchars
	MOVD    $0, R3

mwide:
	SUB     R3, R2, R7
	CMP     $0, R7
	BLE     mwideDone
	ADD     R3, R1, R6
	CMP     $16, R7
	BLT     mwtail
	VLD1    (R6), [V0.B16]
	LDP     (R6), (R8, R9)

mwbody:
	ORR     R8, R9, R10
	TST     R22, R10
	BNE     mwchars
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VUXTL   V0.B8, V4.H8
	VUXTL2  V0.B16, V5.H8
	VST1    [V4.B16, V5.B16], (R0)
	ADD     $32, R0
	MOVD    $0, R13
	VORR    V0.B16, V0.B16, V14.B16
	ADD     $16, R3
	B       mwide

mwchars:
	// Check the block (Keiser and Lemire): V2 the byte one before each, V3 two before, V1 three before.
	VEXT    $15, V0.B16, V14.B16, V2.B16
	VEXT    $14, V0.B16, V14.B16, V3.B16
	VEXT    $13, V0.B16, V14.B16, V1.B16
	VUSHR   $4, V2.B16, V4.B16
	VTBL    V4.B16, [V20.B16], V4.B16
	VAND    V30.B16, V2.B16, V5.B16
	VTBL    V5.B16, [V21.B16], V5.B16
	VUSHR   $4, V0.B16, V6.B16
	VTBL    V6.B16, [V22.B16], V6.B16
	VAND    V5.B16, V4.B16, V4.B16
	VAND    V6.B16, V4.B16, V4.B16
	WORD $0x6e322c65 //    UQSUB V18.B16, V3.B16, V5.B16
	WORD $0x6e312c26 //    UQSUB V17.B16, V1.B16, V6.B16
	VORR    V6.B16, V5.B16, V5.B16
	VAND    V13.B16, V5.B16, V5.B16
	VEOR    V5.B16, V4.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VORR    V0.B16, V0.B16, V14.B16
	// A lead of 4 bytes (F0 or above) here or in the block before: surrogates (R12).
	AND     $0x7f7f7f7f7f7f7f7f, R8, R10
	ADD     R17, R10, R10
	AND     R8, R10, R10
	AND     $0x7f7f7f7f7f7f7f7f, R9, R11
	ADD     R17, R11, R11
	AND     R9, R11, R11
	ORR     R10, R11, R10
	AND     R22, R10, R10
	ORR     R10, R13, R12
	MOVD    R10, R13
	WORD $0x4e2037e4 //    CMGT V0.B16, V31.B16, V4.B16 // b0 a continuation
	WORD $0x4e2237e5 //    CMGT V2.B16, V31.B16, V5.B16 // b1 a continuation
	VAND    V24.B16, V2.B16, V6.B16
	VCMEQ   V31.B16, V6.B16, V6.B16      // b1 the lead of 2 bytes
	WORD $0x4e20a807 //    CMLT V0.B16, V7.B16          // b0 not ASCII
	VORR    V6.B16, V5.B16, V5.B16
	VAND    V4.B16, V5.B16, V5.B16       // b0 ends a char of 2 or more bytes, or is a third byte
	WORD $0x4ee71ca5 //    ORN V7.B16, V5.B16, V5.B16   // kept: those and ASCII
	WORD $0x0f0c84ab //    SHRN $4, V5.H8, V11.B8
	VMOV    V11.D[0], R8
	AND     $0x1111111111111111, R8
	ORR     R8>>3, R8, R8
	AND     $0x0303030303030303, R8
	ORR     R8>>6, R8, R8
	AND     $0x000F000F000F000F, R8
	ORR     R8>>12, R8, R8
	AND     $0xff, R8, R9
	UBFX    $32, R8, $8, R10
	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VORR    V0.B16, V0.B16, V4.B16
	VSLI    $6, V2.B16, V4.B16
	VBIF    V7.B16, V0.B16, V4.B16
	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VUSHR   $2, V2.B16, V5.B16
	VAND    V30.B16, V5.B16, V5.B16
	VSHL    $4, V3.B16, V8.B16
	VORR    V5.B16, V8.B16, V8.B16
	VBIT    V6.B16, V5.B16, V8.B16
	VAND    V7.B16, V8.B16, V8.B16
	CBZ     R12, mwpack
	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VAND    V15.B16, V3.B16, V9.B16
	VCMEQ   V23.B16, V9.B16, V9.B16
	VAND    V15.B16, V1.B16, V10.B16
	VCMEQ   V23.B16, V10.B16, V10.B16
	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VAND    V29.B16, V2.B16, V6.B16
	VSHL    $2, V6.B16, V6.B16
	VUSHR   $4, V0.B16, V7.B16
	VMOVI   $3, V11.B16
	VAND    V11.B16, V7.B16, V7.B16
	VORR    V7.B16, V6.B16, V6.B16
	VSUB    V27.B16, V6.B16, V7.B16
	VBIT    V9.B16, V7.B16, V4.B16
	VCMTST  V31.B16, V6.B16, V6.B16      // no borrow
	VMOVI   $7, V11.B16
	VAND    V11.B16, V3.B16, V7.B16
	VMOVI   $0xD7, V11.B16
	VADD    V11.B16, V7.B16, V7.B16
	VSUB    V6.B16, V7.B16, V7.B16
	VBIT    V9.B16, V7.B16, V8.B16
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VMOVI   $3, V11.B16
	VAND    V11.B16, V5.B16, V7.B16
	VMOVI   $0xDC, V11.B16
	VORR    V11.B16, V7.B16, V7.B16
	VBIT    V10.B16, V7.B16, V8.B16

mwpack:
	VZIP1   V8.B16, V4.B16, V9.B16       // the units of positions 0 to 7
	VZIP2   V8.B16, V4.B16, V10.B16      // 8 to 15
	ADD     R9<<4, R25, R11
	VLD1    (R11), [V6.B16]
	ADD     R10<<4, R25, R11
	VLD1    (R11), [V7.B16]
	MOVBU   (R20)(R9), R9
	MOVBU   (R20)(R10), R10
	VTBL    V6.B16, [V9.B16], V9.B16
	VTBL    V7.B16, [V10.B16], V10.B16
	VST1    [V9.B16], (R0)
	ADD     R9<<1, R0, R0
	SUB     $16, R0, R0
	VST1    [V10.B16], (R0)
	ADD     R10<<1, R0, R0
	SUB     $16, R0, R0
	ADD     $16, R3
	B       mwide

mwtail:
	AND     $4095, R6, R8
	CMP     $4080, R8
	BHI     mwcross
	VLD1    (R6), [V0.B16]
	ADD     $(N_MASK+16), R21, R8
	SUB     R7, R8, R8
	VLD1    (R8), [V1.B16]
	VAND    V1.B16, V0.B16, V0.B16
	VMOV    V0.D[0], R8
	VMOV    V0.D[1], R9
	B       mwbody

mwcross:
	VEOR    V0.B16, V0.B16, V0.B16
	VST1    [V0.B16], (R0)
	MOVD    $0, R8

mwbyte:
	MOVBU   (R6)(R8), R9
	MOVB    R9, (R0)(R8)
	ADD     $1, R8
	CMP     R7, R8
	BLT     mwbyte
	VLD1    (R0), [V0.B16]
	LDP     (R0), (R8, R9)
	B       mwbody

mwideDone:
	WORD $0x6e332dc4 //    UQSUB V19.B16, V14.B16, V4.B16
	VORR    V4.B16, V12.B16, V12.B16
	VMOV    V12.D[0], R8
	VMOV    V12.D[1], R9
	ORR     R8, R9, R10
	CBNZ    R10, minvalid
	SUB     R5, R0, R7
	LSR     $1, R7, R7
	SUB     R2, R3, R8                   // the zeros past the text
	SUB     R8, R7, R7
	MVN     R7, R7
	B       mdone

minvalid:
	MOVD    $0x7fffffffffffffff, R7
	B       mdone

mdone:
	MOVD    $0x7fffffffffffffff, R8
	CMP     R8, R7
	BEQ     mfinish
	TBNZ    $63, R7, mstore16
	// Latin-1: the header 2n+1, as (n+1)+n, n+1 also the bytes the string took.
	ADD     $1, R7, R8
	ADD     R7, R8, R11
	MOVB    R11, (R15)
	ADD     R8, R15, R15
	ADD     $1, R14
	B       mnext

mstore16:
	// UTF-16: the header 2n.
	MVN     R7, R7
	LSL     $1, R7, R8
	MOVB    R8, (R15)
	ADD     R7<<1, R15, R15
	ADD     $1, R15
	ADD     $1, R14
	B       mnext

mfinish:
	MOVD    R14, done+40(FP)
	MOVD    dst+0(FP), R8
	SUB     R8, R15, R8
	MOVD    R8, written+48(FP)
	RET
